      title: '日本作家东野圭吾因结直肠癌去世，终年68岁，遗作《永远的记忆》8月面世',
      source: '环球时报 / 新华社',
      url: 'https://finance.sina.cn/2026-07-28/detail-inikiewh8091984.d.html?vt=4',
      kicker: '人物 · 社会学',
      gist: '《白夜行》《嫌疑人X的献身》的作者东野圭吾7月23日因结直肠癌离世——一位推理作家的死亡，让"肠癌""肠镜检查"冲上热搜，也让一代读者集体告别青春。',
      thread: [
        {t:'讣告', x:'7月27日，东野圭吾官方账号与出版社发布讣告：作家因大肠癌于23日凌晨在东京去世，终年68岁，葬礼已遵家属意愿低调举行。'},
        {t:'生平', x:'1985年以《放学后》获江户川乱步奖出道，40余年创作逾百部，《白夜行》中文版销量超600万册，是在中国读者最多的日本作家之一。'},
        {t:'遗作', x:'"伽利略系列"第11部《永远的记忆》将按原计划于8月5日出版，官方称之为"伽利略最后的谜题"。'},
        {t:'涟漪', x:'消息传出后，"肠癌很多人发现就是中晚期""肠镜检查"等健康话题随之冲上热搜，多地医生借势科普结直肠癌早筛。'}
      ],
      interpretations: [
        {
          q:'为什么一位外国作家去世，中文互联网会有如此大规模的集体哀悼？',
          naive:'以为只是书迷在伤心。',
          lens:'媒介社会学', lensId:'media',
          body:'<b>媒介社会学</b>视角下，东野圭吾的小说与其影视改编构成了一代人的共同媒介记忆：无数人是在地铁上、宿舍里读完《白夜行》的。哀悼一位作家，实际是在哀悼由这些作品串起的自己的一段人生——媒介消费早已是身份与记忆的一部分。',
          aha:'人们悼念的不只是作者，还有那个熬夜读他小说的自己。'
        },
        {
          q:'为什么他的死讯让"肠镜检查"也上了热搜？',
          naive:'以为热搜只是猎奇。',
          lens:'健康社会学', lensId:'health',
          body:'<b>健康社会学</b>指出，公众的健康意识往往由名人患病事件触发而非科普驱动——"名人效应筛查潮"是经典现象。爱运动、生活自律的东野圭吾也罹患肠癌，打破了"健康生活=免疫癌症"的日常信念，迫使人们直面筛查这个平时回避的话题。',
          aha:'一个名人的病历，胜过一百篇科普推文。'
        }
      ],
      theories: [{id:'media',label:'媒介社会学'},{id:'health',label:'健康社会学'}],
