      id: 14,
      title: '年轻人果断辞职刷屏：不是任性，是对失衡职场的无声反抗',
      source: '虎嗅 / 智联招聘数据',
      url: 'https://www.huxiu.com/article/4864792.html',
      kicker: '职场 · 社会学 / 经济学',
      gist: '脉脉、智联数据显示，2026年开年裸辞、安静离职持续刷屏，90后00后占比突出——年轻人不是不爱工作，是不再相信辛苦必有回报。',
      thread: [
        {t:'现象', x:'社交平台上年轻人辞职、安静离职相关内容持续刷屏；多家职场调研显示90后、00后占主动离职群体七成左右。'},
        {t:'诱因', x:'无偿加班、职场PUA、形式主义内耗是主要推力，许多人并非因薪资低，而是因价值感与意义感流失。'},
        {t:'数据', x:'智联招聘报告显示，25—35岁青年职场人撑起离职潮半边天，春节后跳槽意向率明显上升。'},
        {t:'解读', x:'学者指出，这是劳动者争取议价权、对畸形职场结构的集体反弹，而非单纯任性。'}
      ],
      interpretations: [
        {
          q:'为什么越来越多年轻人宁愿裸辞，也不愿忍一忍？',
          naive:'以为他们只是吃不了苦。',
          lens:'不稳定无产阶级', lensId:'precariat',
          body:'<b>不稳定无产阶级</b>（Standing）指出，灵活就业、低保障让年轻人处在随时可被替代的位置——既没有铁饭碗，也没有长期契约。当工作本身就不稳定，裸辞就不再是冒险，而只是从一个临时状态跳到另一个；他们反抗的，是把自己当耗材的职场逻辑。',
          aha:'不是不想稳定，是没人给他稳定的资格。'
        },
        {
          q:'为什么努力却换不来回报，会让人想逃？',
          naive:'觉得熬一熬总会出头。',
          lens:'社会分层', lensId:'stratification',
          body:'<b>社会分层</b>视角下，职场是阶层流动的窄门。当年轻人发现超额付出换不来晋升、薪资跑不赢生活成本、向上通道收窄，相对剥夺感就会压垮意义感。辞职潮表面是个人选择，底层是阶层流动预期变弱的集体症候。',
          aha:'让人想逃的，不是工作，是看不见头的阶梯。'
        }
      ],
      theories: [{id:'precariat',label:'不稳定无产阶级'},{id:'stratification',label:'社会分层'},{id:'econ_labor',label:'劳动力市场'}],
      review: {strength:'strong', disciplines:["soc","econ"]}
