      id: 1,
      title: '台风"红霞"在广东惠州登陆，中心风力14级，中央气象台发布今年首个台风红色预警',
      source: '中央气象台 / 人民网',
      url: 'https://society.people.com.cn/n1/2026/0726/c1008-40767952.html',
      kicker: '公共事件 · 社会学（特大）',
      gist: '"红霞"终于登陆了——14级强台风扑向惠州，今年首个台风红色预警生效，一场自然之力把城市与人又一次推到韧性底线之前。',
      thread: [
        {t:'登陆', x:'26日3时50分前后，今年第12号台风"红霞"(强台风级)在广东惠州市惠东县平海镇登陆，中心附近最大风力14级(45米/秒)。'},
        {t:'红色预警', x:'25日22时，中央气象台发布今年首个台风红色预警；26日6时继续发布台风橙色预警、暴雨红色预警和强对流天气黄色预警。'},
        {t:'响应', x:'广东省防总将防风应急响应提升至Ⅰ级，截至25日16时广东19个市135个区县启动防风、防汛应急响应。'},
        {t:'影响', x:'广东中东部、江西南部、福建南部等地有大暴雨到特大暴雨；"红霞"是今年第3个登陆我国的台风。'}
      ],
      interpretations: [
        {q:'为什么台风还没完全离开，整个社会系统就已经动员到这种程度？',
         naive:'有人觉得停课停运是"过度反应"。',
         lens:'风险社会理论', lensId:'risk_society',
         body:'<b>风险社会理论</b>（贝克）指出，现代社会的核心任务已从"创造财富"转向"管理风险"。提前停课、停运、转移安置，本质是社会为不可精确预测的风险预先支付"确定性成本"——用可计算的经济损失去对冲不可承受的生命损失。这种"宁可十防九空"的制度化预防，正是风险社会的理性应答。',
         aha:'现代社会的成熟，不在于消灭风险，而在于愿意为"还没发生的灾难"提前买单。'},
        {q:'为什么同一场台风，城市核心区与海边渔村、高楼小区与城中村感受到的冲击完全不同？',
         naive:'常以为台风面前人人平等。',
         lens:'城市社会学', lensId:'urban',
         body:'<b>城市社会学</b>提醒我们，城市空间本身就是分层的：加固的写字楼与铁皮棚屋、有地下车库的小区与低洼老宅，对应着完全不同的避险能力。被优先转移安置的，往往正是平日住在城市"边缘空间"的人——台风把城市隐形的空间不平等一次性显影出来。',
         aha:'台风的路径是自然画的，但受灾的地图，是社会画的。'}
      ],
