      id: 3,
      title: '"粤车南下"扩容至大湾区内地9市，7月25日起新增5市车辆可驶入香港',
      source: '广东省港澳办 / 香港特区政府',
      url: 'https://www.gdhmo.gov.cn/xwzx/hzjl/shfz/content/post_109688.html',
      kicker: '区域 · 社会学',
      gist: '从4城试水到9市同享，"粤车南下"再扩容。一脚油门跨三地，大湾区"一小时生活圈"正在从规划变成日常。',
      thread: [
        {t:'扩容', x:'在首批广州、珠海、中山、江门4城基础上，新增深圳、佛山、东莞、惠州、肇庆5市，覆盖粤港澳大湾区内地全部9市。'},
        {t:'实施', x:'7月25日起，新增5市粤车经港珠澳大桥入境香港市区；入境市区每日预约名额由100辆提升至200辆，每车留港最多3天。'},
        {t:'成效', x:'截至5月底，海关累计监管"粤车南下"进出境车辆突破1.3万辆次；入境市区部分约8400个申请获批准，累计预约出行约6700车次。'},
        {t:'路线', x:'粤港双方明确，目标在2027年第一季度前把政策进一步扩展至广东全省21个城市。'}
      ],
      interpretations: [
        {q:'为什么"自驾去香港"这件小事，值得用跨制度协同去推动？',
         naive:'觉得不过是方便自驾游。',
         lens:'移民社会学', lensId:'migration',
         body:'<b>移民社会学</b>研究人口与要素的跨界流动如何被制度塑造。过去内地居民驾车入港需满足严苛条件，"粤车南下"把跨境流动的门槛从"身份特权"降为"普遍资格"，本质是制度性地松绑了一种日常化的跨界流动——流动越便利，区域共同体的感觉越真实。',
         aha:'共同体的形成，往往始于"说走就走"被制度允许。'},
        {q:'大湾区9市被一条大桥连起来，城市之间的"中心-边缘"格局会变吗？',
         naive:'以为路通了大家就一样富。',
         lens:'核心-边缘', lensId:'core_periphery',
         body:'<b>核心-边缘</b>结构揭示：基础设施联通首先利好枢纽城市，资源更易向核心集聚，边缘城市若只当"过道"反而可能被进一步虹吸。但"粤车南下"双向开通消费流，让惠州、肇庆等新增城市也能把本地客群直接输送进香港市场——能否把"通道"变成"节点"，取决于配套产业与服务的承接能力。',
         aha:'路通只是起点，真正决定贫富落差的，是边缘城市能不能在人流里接住自己的生意。',
         research:{ title:'Network Structure and Synergy Characteristics in the Guangdong-Hong Kong-Macao Greater Bay Area', authors:'Applied Sciences 研究论文', year:2025, venue:'Applied Sciences', url:'https://doi.org/10.3390/app15147705', summary:'基于复杂网络方法刻画粤港澳大湾区城市间的关联结构与协同特征，识别核心城市与边缘节点的嵌套关系，量化交通与要素流动对区域一体化的驱动作用。其"核心-边缘"网络结论，为"粤车南下"这类打破行政壁垒、强化次中心城市对外连接的政策提供了空间结构层面的学理支撑。', fromNode:'core_periphery' }}
      ],
      theories: [{id:'migration',label:'移民社会学'},{id:'urban',label:'城市社会学'},{id:'core_periphery',label:'核心-边缘'}],
