         body:'<b>经济增长</b>理论关注产业能级与长期动能。造船是技术、资本与供应链高度密集的装备产业，三大指标领跑意味着从设计、配套到总装的完整能力已具全球竞争力——它拉动的不仅是船坞，更是上下游一整条制造链。',
