         lens:'收入分配与不平等', lensId:'econ_inequality',
         body:'<b>收入分配与不平等</b>在区域维度表现为省际发展差距。安徽借长三角一体化与新能源汽车产业链，把新兴动能做成了硬增量；而湖南受传统制造、工程机械与地产链调整拖累，增长承压——同一张十强榜单，折射的是区域产业结构的分化。',
