         lens:'健康社会学', lensId:'health',
         body:'<b>健康社会学</b>指出健康资源沿阶层与城乡分布不均。规划强调基层中医馆、适宜技术下沉与县域特色专科，正是要把优质健康服务推到医疗资源薄弱的末端——健康公平不只在三甲医院，也在家门口的中医阁。',
