        {t:'依据', x:'多国研究指向社媒过度使用与青少年抑郁、焦虑相关。'},
        {t:'争议', x:'有专家质疑“一禁了之”收效有限，青少年会绕开限制。'},
        {t:'转向', x:'讨论焦点逐渐从“管孩子”转向“追究平台设计责任”。'}
