      interpretations: [
        {q:'为什么青春期正是社交媒体伤害最深的年龄段？',
         naive:'家长常以为：不就是玩手机上瘾，长大自然就好了。',
         lens:'心理健康', lensId:'psy_mental_health',
         body:'<b>心理健康</b>研究显示，12—15岁处于大脑与自我认同高速发育的敏感窗口，对社会比较、同伴评价与即时反馈格外敏感。无限滚动与点赞机制不断放大“别人都过得更好”的落差，抑郁与焦虑风险因此在这个阶段显著抬升。',
         aha:'不是孩子太脆弱，而是平台的设计，恰好精准命中了青春期最不设防的地方。',
         research:{ title:'Social Media Use and Depressive Symptoms During Early Adolescence', authors:'Nagata J.M., Otmar C.D., Shim J., et al.', year:2025, venue:'JAMA Network Open', url:'https://www.medsci.cn/article/show_article.do?id=10648e9919e6', summary:'基于美国ABCD队列近1.2万名9—10岁儿童的3年追踪（随机截距交叉滞后模型）发现：个体社媒使用时间高于自身均值时，次年抑郁症状显著加重，而反向（抑郁导致多用）不成立——为“低龄限制”提供了纵向因果方向的证据。', fromNode:'psy_mental_health' }},
        {q:'为什么明知有害，青少年还是很难放下社交媒体？',
         naive:'常被归结为：自制力差、意志力不够。',
         lens:'社会影响', lensId:'psy_social_influence',
         body:'<b>社会影响</b>研究表明，人在群体中会强烈受制于从众与归属需求。当同龄人几乎全部在某个平台社交，退出就意味着被排斥在同伴网络之外——这不是个人意志的失败，而是同伴压力下的理性选择。',
         aha:'让孩子“别玩了”这么难，是因为退出的代价，是被整个同龄圈子边缘化。'}
      ],
      theories: [{id:'psy_mental_health',label:'心理健康'},{id:'psy_social_influence',label:'社会影响'},{id:'digital',label:'数字社会学'}],
      major: true,
      platforms: ['微博热搜','知乎热榜','百度热搜','今日头条'],
      review: {strength:'strong', disciplines:['psy','soc']},
